        let tex: String = "\n            \\ro \\ae 1 1.1.1 | \\ae 2 2.1 | \\ae 3 3.1 |\n            4.3.4*4 |\n            \\ae 1 1.1.1 | \\ae 2 2.1 | \\ae 3 3.1 |\n            4.3.4*4 |\n            \\ae (1 3) 1.1.1 | \\ae 2 \\rc 3 2.1 |\n        "
